        0xff8b => 0x30d2,
        0xff8c => 0x30d5,
        0xff8d => 0x30d8,
        0xff8e => 0x30db,
        0xff8f => 0x30de,
        0xff90 => 0x30df,
        0xff91 => 0x30e0,
        0xff92 => 0x30e1,
        0xff93 => 0x30e2,
        0xff94 => 0x30e4,
        0xff95 => 0x30e6,
        0xff96 => 0x30e8,
        0xff97 => 0x30e9,
        0xff98 => 0x30ea,
