}

fn normalizeHalfwidthHangulJamo(cp: u21) u21 {
    return switch (cp) {
        0xffa0 => 0x1160,
        0xffa1 => 0x1100,
        0xffa2 => 0x1101,
        0xffa3 => 0x11aa,
        0xffa4 => 0x1102,
        0xffa5 => 0x11ac,
        0xffa6 => 0x11ad,
        0xffa7 => 0x1103,
