}

fn normalizeHiraganaToKatakana(cp: u21) u21 {
    return if (cp >= 0x3041 and cp <= 0x3096) cp + 0x60 else cp;
}

fn applyJapaneseVoiceMark(cp: u21, mark: u21) ?u21 {
    if (isJapaneseHandakutenMark(mark)) {
        return switch (cp) {
            0x306f => 0x3071,
            0x3072 => 0x3074,
            0x3075 => 0x3077,
            0x3078 => 0x307a,
            0x307b => 0x307d,
            0x30cf => 0x30d1,
            0x30d2 => 0x30d4,
            0x30d5 => 0x30d7,
            0x30d8 => 0x30da,
            0x30db => 0x30dd,
            else => null,
        };
    }
    return switch (cp) {
        0x3046 => 0x3094,
        0x304b => 0x304c,
        0x304d => 0x304e,
        0x304f => 0x3050,
        0x3051 => 0x3052,
        0x3053 => 0x3054,
        0x3055 => 0x3056,
        0x3057 => 0x3058,
        0x3059 => 0x305a,
        0x305b => 0x305c,
        0x305d => 0x305e,
        0x305f => 0x3060,
        0x3061 => 0x3062,
        0x3064 => 0x3065,
        0x3066 => 0x3067,
        0x3068 => 0x3069,
        0x306f => 0x3070,
        0x3072 => 0x3073,
        0x3075 => 0x3076,
        0x3078 => 0x3079,
        0x307b => 0x307c,
        0x30a6 => 0x30f4,
        0x30ab => 0x30ac,
        0x30ad => 0x30ae,
        0x30af => 0x30b0,
        0x30b1 => 0x30b2,
        0x30b3 => 0x30b4,
        0x30b5 => 0x30b6,
        0x30b7 => 0x30b8,
        0x30b9 => 0x30ba,
        0x30bb => 0x30bc,
        0x30bd => 0x30be,
        0x30bf => 0x30c0,
        0x30c1 => 0x30c2,
        0x30c4 => 0x30c5,
        0x30c6 => 0x30c7,
        0x30c8 => 0x30c9,
        0x30cf => 0x30d0,
        0x30d2 => 0x30d3,
        0x30d5 => 0x30d6,
        0x30d8 => 0x30d9,
        0x30db => 0x30dc,
        0x30ef => 0x30f7,
        0x30f0 => 0x30f8,
        0x30f1 => 0x30f9,
        0x30f2 => 0x30fa,
        else => null,
    };
}

fn appendCjkTokens(tokens: *TokenList, bytes: []const u8, options: TokenizerOptions) !void {
    var offsets = std.ArrayList(usize).empty;
    defer offsets.deinit(tokens.allocator);

    var i: usize = 0;
    while (i < bytes.len) {
        try offsets.append(tokens.allocator, i);
        i += decodeUtf8(bytes, i).len;
    }

    if (options.emit_cjk_unigrams) {
        for (0..offsets.items.len) |idx| {
            const start = offsets.items[idx];
            const end = if (idx + 1 < offsets.items.len) offsets.items[idx + 1] else bytes.len;
            const token = try tokens.allocator.dupe(u8, bytes[start..end]);
            try tokens.appendOwned(token, options.max_token_bytes);
        }
    }

    if (options.emit_cjk_bigrams and offsets.items.len >= 2) {
        for (0..offsets.items.len - 1) |idx| {
            const start = offsets.items[idx];
            const end = if (idx + 2 < offsets.items.len) offsets.items[idx + 2] else bytes.len;
            const token = try tokens.allocator.dupe(u8, bytes[start..end]);
            try tokens.appendOwned(token, options.max_token_bytes);
        }
    }
}

