        try std.testing.expectEqual(entry.value_ptr.*, actual.text);
        try std.testing.expectEqual(@as(u32, 0), actual.kind);
    }

    freqs.clearRetainingCapacity();
    _ = term_arena.reset(.retain_capacity);
